import 'dart:convert';

import 'package:codeguardian_core/codeguardian_core.dart';

import 'html_report.dart' show computeReportScore;

/// Generates a single, self-contained **dashboard** HTML file from findings
/// (and, optionally, the AI/deterministic fix suggestions for them).
///
/// Unlike [generateHtmlReport] (a report document), this mirrors the Flutter
/// dashboard's look and structure -- a dark, purple-accented UI with a score
/// header, a filterable findings table, and an "AI-suggested fixes" section
/// showing each fix's confidence and a colour-coded unified-diff preview.
///
/// It is fully self-contained (inline CSS/JS + embedded data): it opens
/// directly from disk with no server, build step, or network access, so it
/// can be dropped into a project's report output right next to `report.html`.
///
/// [fixes] entries use the fixer's `Fix` JSON shape (`ruleId`, `file`,
/// `diff`, `confidence`) plus an optional `explanation`.
///
/// [generatedAt] defaults to now; pass an explicit value for reproducible
/// output (e.g. in tests).
String generateDashboardHtml(
  List<Map<String, dynamic>> findings, {
  List<Map<String, dynamic>> fixes = const [],
  String title = 'CodeGuardian AI Dashboard',
  DateTime? generatedAt,
}) {
  final score = computeReportScore(findings);
  final counts = <String, int>{};
  for (final f in findings) {
    final s = f['severity'] as String? ?? 'info';
    counts[s] = (counts[s] ?? 0) + 1;
  }

  final timestamp = (generatedAt ?? DateTime.now()).toUtc().toIso8601String();

  final badges = StringBuffer();
  for (final severity in const ['critical', 'high', 'medium', 'low', 'info']) {
    final count = counts[severity] ?? 0;
    if (count == 0) continue;
    badges.write('<span class="chip sev-$severity">$count '
        '${_titleCase(severity)}</span>');
  }

  return (StringBuffer()
        ..writeln('<!doctype html>')
        ..writeln('<html lang="en">')
        ..writeln('<head>')
        ..writeln('<meta charset="utf-8">')
        ..writeln('<meta name="viewport" content="width=device-width, '
            'initial-scale=1">')
        ..writeln('<title>${_escapeHtml(title)}</title>')
        ..writeln('<style>$_dashboardCss</style>')
        ..writeln('</head>')
        ..writeln('<body>')
        ..writeln('<header class="app-header">')
        ..writeln('<div class="brand">')
        ..writeln('<span class="brand-mark">&#9683;</span>')
        ..writeln('<h1 class="grad">${_escapeHtml(title)}</h1>')
        ..writeln('</div>')
        ..writeln('<div class="score" style="--sc:${_scoreColor(score)}">'
            '<span class="score-num">${score.toStringAsFixed(0)}</span>'
            '<span class="score-label">Health score</span></div>')
        ..writeln('</header>')
        ..writeln('<p class="meta">Generated $timestamp &middot; '
            '${findings.length} finding${findings.length == 1 ? '' : 's'} '
            '&middot; ${fixes.length} suggested fix'
            '${fixes.length == 1 ? '' : 'es'}</p>')
        ..writeln('<div class="chip-row">$badges</div>')
        ..writeln('<nav class="tabs">')
        ..writeln('<button class="tab active" data-tab="findings">'
            'Findings <span class="pill" id="findings-count">0</span></button>')
        ..writeln('<button class="tab" data-tab="fixes">AI Fixes '
            '<span class="pill" id="fixes-count">0</span></button>')
        ..writeln('</nav>')
        ..writeln('<main>')
        ..writeln('<section id="tab-findings" class="tab-panel active">')
        ..writeln('<div class="toolbar">')
        ..writeln('<input id="search" type="search" '
            'placeholder="Search findings (rule, file, message)…">')
        ..writeln('<div id="sev-filters" class="sev-filters"></div>')
        ..writeln('</div>')
        ..writeln('<div class="table-wrap"><table id="findings-table">'
            '<thead><tr>'
            '<th>Severity</th><th>Category</th><th>Rule</th>'
            '<th>File</th><th>Line</th><th>Message</th>'
            '</tr></thead><tbody></tbody></table></div>')
        ..writeln('<p class="empty" id="findings-empty" hidden>'
            'No findings match the current filters.</p>')
        ..writeln('</section>')
        ..writeln('<section id="tab-fixes" class="tab-panel">')
        ..writeln('<div id="fixes-list"></div>')
        ..writeln('<p class="empty" id="fixes-empty" hidden>'
            'No suggested fixes.</p>')
        ..writeln('</section>')
        ..writeln('</main>')
        ..writeln('<footer>Generated by CodeGuardian AI</footer>')
        ..writeln('<script>')
        ..writeln('var FINDINGS = ${_embedJson(findings)};')
        ..writeln('var FIXES = ${_embedJson(fixes)};')
        ..writeln(_dashboardScript)
        ..writeln('</script>')
        ..writeln('</body>')
        ..writeln('</html>'))
      .toString();
}

/// Convenience overload of [generateDashboardHtml] for callers that already
/// have [Finding]/`Fix`-shaped objects.
String generateDashboardHtmlFromFindings(
  List<Finding> findings, {
  List<Map<String, dynamic>> fixes = const [],
  String title = 'CodeGuardian AI Dashboard',
  DateTime? generatedAt,
}) {
  return generateDashboardHtml(
    findings.map((f) => f.toJson()).toList(),
    fixes: fixes,
    title: title,
    generatedAt: generatedAt,
  );
}

String _embedJson(Object? data) {
  // Escape every '<' as its unicode escape so the literal sequence
  // `</script` can never appear in the raw HTML and prematurely close the
  // inline <script> tag (JSON.parse treats \u003c and '<' identically).
  final lessThan = String.fromCharCodes([0x5c, 0x75, 0x30, 0x30, 0x33, 0x63]);
  final buffer = StringBuffer();
  for (final rune in jsonEncode(data).runes) {
    if (rune == 0x3c) {
      buffer.write(lessThan);
    } else {
      buffer.writeCharCode(rune);
    }
  }
  return buffer.toString();
}

String _escapeHtml(String text) => text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

String _titleCase(String value) =>
    value.isEmpty ? value : value[0].toUpperCase() + value.substring(1);

String _scoreColor(num score) {
  if (score >= 90) return '#34d399';
  if (score >= 70) return '#f59e0b';
  if (score >= 50) return '#fb923c';
  return '#f87171';
}

const _dashboardCss = r'''
