  background:linear-gradient(90deg,var(--primary-deep),var(--primary));
  -webkit-background-clip:text;background-clip:text;color:transparent}
.score{display:flex;flex-direction:column;align-items:center;
  border:1px solid var(--border);border-radius:14px;padding:8px 18px;background:var(--surface)}
.score-num{font-size:30px;font-weight:800;color:var(--sc)}
.score-label{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}
.meta{color:var(--muted);font-size:13px;margin:14px 0 10px}
.chip-row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}
.chip{font-size:12px;font-weight:700;padding:4px 10px;border-radius:999px;
  border:1px solid var(--border);background:var(--surface)}
.sev-critical{color:#fca5a5;border-color:#7f1d1d}
.sev-high{color:#fdba74;border-color:#7c2d12}
.sev-medium{color:#fcd34d;border-color:#78350f}
.sev-low{color:#93c5fd;border-color:#1e3a8a}
.sev-info{color:#a5b4fc;border-color:#312e81}
.tabs{display:flex;gap:8px;border-bottom:1px solid var(--border);margin-bottom:18px}
.tab{background:none;border:none;color:var(--muted);font-size:14px;font-weight:600;
  padding:10px 14px;cursor:pointer;border-bottom:2px solid transparent}
.tab.active{color:var(--text);border-bottom-color:var(--primary)}
.tab .pill{background:var(--border);color:var(--text);border-radius:999px;
  padding:1px 8px;font-size:11px;margin-left:6px}
.tab-panel{display:none}
.tab-panel.active{display:block}
.toolbar{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-bottom:14px}
#search{flex:1;min-width:240px;background:var(--code);border:1px solid var(--border);
  border-radius:10px;color:var(--text);padding:10px 12px;font-size:13px}
.sev-filters{display:flex;gap:12px;flex-wrap:wrap}
.sev-filters label{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:5px}
.table-wrap{overflow-x:auto;border:1px solid var(--border);border-radius:12px}
table{border-collapse:collapse;width:100%;font-size:13px}
th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--border);
  vertical-align:top}
th{color:var(--muted);font-weight:600;position:sticky;top:0;background:var(--surface)}
tbody tr:hover{background:rgba(168,85,247,.06)}
td.file,td.rule{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  color:var(--muted);font-size:12px}
.sev-tag{font-weight:700;text-transform:capitalize}
.sev-tag.critical{color:var(--red)} .sev-tag.high{color:#fb923c}
.sev-tag.medium{color:var(--orange)} .sev-tag.low{color:#93c5fd} .sev-tag.info{color:var(--muted)}
.card{border:1px solid var(--border);border-radius:14px;background:var(--surface);
  padding:16px;margin-bottom:16px}
