.rule-pill{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;font-weight:700;
  color:var(--primary);background:rgba(168,85,247,.14);border:1px solid rgba(168,85,247,.4);
  border-radius:6px;padding:3px 9px}
