.conf.hi{color:var(--green);background:rgba(52,211,153,.15);border:1px solid rgba(52,211,153,.5)}
.conf.mid{color:var(--orange);background:rgba(245,158,11,.15);border:1px solid rgba(245,158,11,.5)}
