.diff .del{background:rgba(248,113,113,.15);color:#fca5a5}
.diff .hunk{color:#7c89ff;font-weight:600}
.diff .meta{color:var(--muted)}
.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}
.btn{border-radius:8px;padding:8px 14px;font-size:13px;font-weight:600;cursor:pointer;
  border:1px solid var(--border);background:transparent;color:var(--text)}
