.btn.approve{background:var(--primary);border-color:var(--primary);color:#fff}
.btn:disabled{opacity:.5;cursor:default}
.empty{color:var(--muted);text-align:center;padding:30px}
footer{color:var(--muted);font-size:12px;margin-top:30px;text-align:center}
''';

const _dashboardScript = r'''
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
var SEVS=['critical','high','medium','low','info'];
var active={critical:true,high:true,medium:true,low:true,info:true};

function initFilters(){
  var box=document.getElementById('sev-filters');
  SEVS.forEach(function(s){
    var id='f-'+s;
    var l=document.createElement('label');
    l.innerHTML='<input type="checkbox" id="'+id+'" checked> '+s;
    box.appendChild(l);
    l.querySelector('input').addEventListener('change',function(e){
      active[s]=e.target.checked; renderFindings();});
  });
  document.getElementById('search').addEventListener('input',renderFindings);
}

function renderFindings(){
  var q=(document.getElementById('search').value||'').toLowerCase();
  var tbody=document.querySelector('#findings-table tbody');
  tbody.innerHTML='';
  var shown=0;
  FINDINGS.forEach(function(f){
    var sev=f.severity||'info';
    if(!active[sev])return;
    var hay=((f.ruleId||'')+' '+(f.file||'')+' '+(f.message||'')).toLowerCase();
    if(q&&hay.indexOf(q)<0)return;
    shown++;
    var tr=document.createElement('tr');
    tr.innerHTML='<td><span class="sev-tag '+sev+'">'+esc(sev)+'</span></td>'+
      '<td>'+esc(f.category)+'</td>'+
      '<td class="rule">'+esc(f.ruleId)+'</td>'+
      '<td class="file">'+esc(f.file)+'</td>'+
      '<td>'+esc(f.line)+'</td>'+
      '<td>'+esc(f.message)+'</td>';
    tbody.appendChild(tr);
  });
  document.getElementById('findings-empty').hidden=shown>0;
  document.getElementById('findings-count').textContent=FINDINGS.length;
}

function renderDiff(diff){
  var out='';
  (diff||'').replace(/\r\n/g,'\n').split('\n').forEach(function(line){
    if(line==='')return;
    var cls='';
    if(line.indexOf('@@')===0)cls='hunk';
    else if(line.indexOf('+++')===0||line.indexOf('---')===0||
            line.indexOf('diff ')===0||line.indexOf('index ')===0)cls='meta';
    else if(line[0]==='+')cls='add';
    else if(line[0]==='-')cls='del';
    out+='<div class="ln '+cls+'">'+esc(line)+'</div>';
  });
  return '<div class="diff">'+out+'</div>';
}

function confClass(c){return c>=0.8?'hi':c>=0.5?'mid':'lo';}

function renderFixes(){
  var list=document.getElementById('fixes-list');
  list.innerHTML='';
  FIXES.forEach(function(fx,i){
    var pct=Math.round((fx.confidence!=null?fx.confidence:1)*100);
    var card=document.createElement('div');
    card.className='card';
    card.innerHTML=
      '<div class="card-top">'+
      '<span class="rule-pill">'+esc(fx.ruleId)+'</span>'+
      '<span class="conf '+confClass(fx.confidence!=null?fx.confidence:1)+'">'+pct+'% confidence</span>'+
      '<span class="status" id="st-'+i+'"></span>'+
      '</div>'+
      '<div class="file">'+esc(fx.file)+'</div>'+
      (fx.explanation?'<p class="explain">'+esc(fx.explanation)+'</p>':'')+
      renderDiff(fx.diff)+
      '<div class="actions">'+
      '<button class="btn reject" id="rj-'+i+'">Reject</button>'+
      '<button class="btn approve" id="ap-'+i+'">Approve</button>'+
      '</div>';
    list.appendChild(card);
    card.querySelector('#ap-'+i).addEventListener('click',function(){mark(i,'approved','Approved');});
    card.querySelector('#rj-'+i).addEventListener('click',function(){mark(i,'rejected','Rejected');});
  });
  document.getElementById('fixes-empty').hidden=FIXES.length>0;
  document.getElementById('fixes-count').textContent=FIXES.length;
}

function mark(i,cls,label){
  var st=document.getElementById('st-'+i);
  st.className='status '+cls; st.textContent=label;
  document.getElementById('ap-'+i).disabled=true;
  document.getElementById('rj-'+i).disabled=true;
}

function initTabs(){
  document.querySelectorAll('.tab').forEach(function(t){
    t.addEventListener('click',function(){
      document.querySelectorAll('.tab').forEach(function(x){x.classList.remove('active');});
      document.querySelectorAll('.tab-panel').forEach(function(x){x.classList.remove('active');});
      t.classList.add('active');
      document.getElementById('tab-'+t.dataset.tab).classList.add('active');
    });
  });
}

initFilters(); initTabs(); renderFindings(); renderFixes();
''';
